tool_input.command:
cd packages/nodes-base/nodes/KoBoToolbox && python3 - <<'E'
p='KoBoToolbox.node.ts'
s=open(p).read()
s=s.replace("""					const rawIds = this.getNodeParameter('submissionIds', i) as string;
					const status = this.getNodeParameter('validationStatus', i) as string;
""","""					const rawIds = this.getNodeParameter('submissionIds', i);
					const status = this.getNodeParameter('validationStatus', i);

					if (typeof rawIds !== 'string' || typeof status !== 'string') {
						throw new NodeOperationError(this.getNode(), 'Invalid submission IDs or status', {
							itemIndex: i,
						});
					}

""")
open(p,'w').write(s)
E
git diff KoBoToolbox.node.ts | grep -n " as "
